function processNumber(number) {
    if (number < 3) {
        return 3;
    } else if (Number.isInteger(number)) {
        return number;
    } else {
        const decimalPart = number - Math.floor(number);
        if (decimalPart > 0.5) {
            return Math.ceil(number);
        } else if (decimalPart > 0.4) {
            return Math.floor(number) + 0.5;
        } else {
            return Math.floor(number) + 0.5;
        }
    }
}

async function getCountForStatus(status, userId) {
    try {
        return await Enquiry.count({ where: { status: status, salesId: userId } });
    } catch (error) {
        throw error;
    }
}

