exports.getEnquiryByStatus = async (req, res, next) => {
    try {
        const where = {}
        if (req.query.status) {
            where.status = req.query.status
        }
        if (req.query.enquiryId) {
            where.id = req.query.enquiryId
        }
        const customer_where = {};

        if (req.query.customerName) {
            customer_where[Op.or] = [
                sequelize.where(
                    sequelize.fn('CONCAT', sequelize.col('firstName'), ' ', sequelize.col('lastName'), ' ', sequelize.col('primary_phone')),
                    {
                        [Op.like]: `%${req.query.customerName}%`
                    }
                ),
                sequelize.where(
                    sequelize.fn('CONCAT', sequelize.col('lastName'), ' ', sequelize.col('firstName'), ' ', sequelize.col('primary_phone')),
                    {
                        [Op.like]: `%${req.query.customerName}%`
                    }
                )
            ];
        }

        const enquiries = await Enquiry.findAll({
            where: { ...where, salesId: req.userId },
            order: [["id", "DESC"]],
            include: [
                {
                    model: Customer,
                    where: customer_where,
                    include: {
                        model: User,
                        as: "sales"
                    }
                },
                EnquiryStatus
            ]
        });

        if (enquiries && enquiries.length > 0) {
            for (var i = 0; i < enquiries.length; i++) {
                const enquiry = enquiries[i];

                const products = [];
                const selectedmaterial = await SelectedMaterial.findAll({
                    where: { enquiryId: enquiry.id },
                    include: [Material],
                });

                for (const i of selectedmaterial) {
                    const materials = await Material.findOne({
                        where: { id: i.materialId },
                    });
                    if (!products.includes(materials.name)) {
                        products.push(materials.name);
                    }
                }

                enquiry.dataValues.category = products;

            }
        }

        res.status(200).json({
            message: "Enquiry data fetched",
            data: enquiries,
            status: true
        })
    } catch (e) {
        next(e)
    }
}

exports.enquiryStatusCount = async (req, res, next) => {
    try {
        const user = await User.findOne({ where: { id: req.userId } });
        dataFound(user.type != "sales-person", 400, "You are not a Sales person");

        const total = await Enquiry.count({ where: { salesId: req.userId } })

        const obj = {
            fresh: await getCountForStatus("fresh", req.userId),
            inprogress: await getCountForStatus("fresh", req.userId),
            completed: await getCountForStatus("completed", req.userId),
            measurement_complete: await getCountForStatus("measurement-complete", req.userId),
            installer_assigned: await getCountForStatus("installer-assigned", req.userId),
            installation_started: await getCountForStatus("installation-started", req.userId),
            order_confirmed: await getCountForStatus("order-confirmed", req.userId),
            qc_complete: await getCountForStatus("qc-complete", req.userId),
            cancelled: await getCountForStatus("cancelled", req.userId),
            total
        }
        res.status(200).json({
            message: "Counts Fetched",
            data: obj,
            status: true
        })
    } catch (e) {
        next(e)
    }
}

