exports.syncCustomerDataFromAX = async (req, res, next) => {
    try {
        const data = []
        const updatedData = []
        for (var i = 0; i < req.body.length; i++) {
            const customer = req.body[i]
            const address = req.body[i].address
            const customer_data = await Customer.findOne({ where: { ACCOUNTNUM: customer.ACCOUNTNUM } })

            if (!customer_data) {
                const newCustomer = await Customer.create({
                    firstName: customer.NAME.split(" ")[0],
                    lastName: customer.NAME.split(" ")[1],
                    primary_phone: customer.ACX_MOBILENO == '' ? null : customer.ACX_MOBILENO,
                    secondary_phone: customer.ACX_PHONENO == '' ? null : customer.ACX_PHONENO,
                    primary_email: customer.ACX_EMAIL == '' ? null : customer.ACX_EMAIL,
                    secondary_email: customer.ACX_EMAIL2 == '' ? null : customer.ACX_EMAIL2,
                    type: customer.TYPE == 1 ? "individual" : "company",
                    GST: customer.GST,
                    ACCOUNTNUM: customer.ACCOUNTNUM == '' ? null : customer.ACCOUNTNUM
                })
                data.push(newCustomer)

                if (address) {
                    const newAddress = await Address.create({
                        contactPerson: address.LOCATIONNAME,
                        street: address.COUNTRYREGIONID,
                        city: address.CITY,
                        address: address.ADDRESS,
                        state: address.STATE,
                        pincode: address.ZIPCODE,
                        type: address.TYPE == 1 ? "billing" : "delivery",
                        customerId: newCustomer.id
                    })
                    data.push(newAddress)
                }
            } else {
                const cData = await customer_data.update({
                    firstName: customer.NAME.split(" ")[0],
                    lastName: customer.NAME.split(" ")[1],
                    primary_phone: customer.ACX_MOBILENO,
                    secondary_phone: customer.ACX_PHONENO,
                    primary_email: customer.ACX_EMAIL,
                    secondary_email: customer.ACX_EMAIL2,
                    GST: customer.GST,
                    type: customer.TYPE == 1 ? "individual" : "company",
                })
                updatedData.push(cData)
                const address_data = await Address.findOne({ where: { customerId: customer_data.id } })
                if (!address_data && address) {
                    await Address.create({
                        contactPerson: address.LOCATIONNAME,
                        street: address.COUNTRYREGIONID,
                        city: address.CITY,
                        address: address.ADDRESS,
                        state: address.STATE,
                        pincode: address.ZIPCODE,
                        type: address.TYPE == 1 ? "billing" : "delivery",
                        customerId: customer_data.id
                    })
                } else if (address && address_data) {
                    await address_data.update({
                        contactPerson: address.LOCATIONNAME,
                        street: address.COUNTRYREGIONID,
                        city: address.CITY,
                        address: address.ADDRESS,
                        state: address.STATE,
                        pincode: address.ZIPCODE,
                        type: address.TYPE == 1 ? "billing" : "delivery",
                        customerId: customer_data.id
                    })
                }
            }
        }
        res.json({ message: "done", newData: data, status: true, updatedData })
    } catch (e) { next(e) }
}
