                contactNumber: req.body.delivery.contactNumber,
                latitude: req.body.delivery.latitude,
                longitude: req.body.delivery.longitude,
                mode_of_deliveries: req.body.delivery.mode_of_deliveries,
                payment_terms: req.body.delivery.payment_terms,
                tailor_vendors: req.body.delivery.tailor_vendors,
                tailor_vendors_id: req.body.delivery.tailor_vendors_id,
                transports: req.body.delivery.transports,
