exports.syncCurtainFromAX = async (req, res, next) => {
    try {

        const arr = []
        for (var i = 0; i < req.body.length; i++) {
            const fabric = req.body[i]
            const fabric_data = await CurtainFabric.findOne({ where: { item_id: fabric.ITEMID } });
            if (fabric.ITEMGROUPID) {
                if (!fabric_data) {
                    const obj = {
                        item_id: fabric.ITEMID,
                        fabric: fabric.NAMEALIAS,
                        width: fabric.WIDTH,
                        repeat_horizontal: fabric.REPEATHORIZONTAL,
                        repeat_vertical: fabric.REPEATVERTICAL,
                        book_name: fabric.COLLECTIONCODE,
                        brand_name: fabric.BRANDCODE,
                        price: fabric.MAXIMUMRETAILPRICE_IN,
                        tax: fabric.TAXVALUE,
                        category: fabric.CATEGORYCODE,
                        item_group: fabric.ITEMGROUPID,
                        sales_price: fabric["SALES PRICE"] || 0
                    }
                    arr.push(obj)
                }
                else {
                    await fabric_data.update({
                        fabric: fabric.NAMEALIAS,
                        width: fabric.WIDTH,
                        repeat_horizontal: fabric.REPEATHORIZONTAL,
                        repeat_vertical: fabric.REPEATVERTICAL,
                        brand_name: fabric.BRANDCODE,
                        book_name: fabric.COLLECTIONCODE,
                        price: fabric.MAXIMUMRETAILPRICE_IN,
                        sales_price: fabric["SALES PRICE"] || 0,
                        tax: fabric.TAXVALUE,
                        category: fabric.CATEGORYCODE,
                        item_group: fabric.ITEMGROUPID
                    })
                }
            }
        }

        await CurtainFabric.bulkCreate(arr)

        return res.send({
            message: "Curtain Data Synced",
            status: true
        })
    } catch (e) {
        next(e)
    }
}

