exports.syncCustomerAddressData = async (req, res, next) => {
    try {
        const response = await axios.get(`http://localhost:1232/address`)

        const arr = []
        for (var i = 0; i < response.data.data.length; i++) {
            const customer = response.data.data[i]

            const customer_data = await Customer.findOne({ where: { ACCOUNTNUM: customer.AccountNum } })

            if (customer_data && customer.ISPRIMARY == 1) {
                const billing = await Address.findOne({ where: { customerId: customer_data.id, type: "billing" } })
                if (!billing) {
                    await Address.create({
                        contactPerson: customer.LOCATIONNAME,
                        street: customer.COUNTRYREGIONID,
                        city: customer.CITY,
                        address: customer.ADDRESS,
                        state: customer.STATE,
                        pincode: customer.ZIPCODE,
                        type: "billing",
                        customerId: customer_data.id
                    })
                }
            }
            else if (customer_data && customer.ISPRIMARY != 1) {
                const delivery = await Address.findOne({ where: { customerId: customer_data.id, type: "delivery" } })
                if (!delivery) {
                    await Address.create({
                        contactPerson: customer.LOCATIONNAME,
                        street: customer.COUNTRYREGIONID,
                        city: customer.CITY,
                        address: customer.ADDRESS,
                        state: customer.STATE,
                        pincode: customer.ZIPCODE,
                        type: "delivery",
                        customerId: customer_data.id
                    })
                }
            }

        }
        await Address.bulkCreate(arr)
        res.send("done")
    } catch (e) { next(e) }
}
exports.getAllcustomer = async (req, res, next) => {
    try {
        const customers = await Customer.findAll({ order: [["id", "DESC"]], include: { model: Enquiry, include: [EnquiryStatus] } });

        const arr = []
        for (var i = 0; i < customers.length; i++) {

            const billingAddress = await Address.findOne({ where: { customerId: customers[i].id, type: "billing" } });
            const deliveryAddress = await Address.findOne({ where: { customerId: customers[i].id, type: "delivery" } });

            const obj = {
                customer: customers[i],
                billing: billingAddress,
                delivery: deliveryAddress
            }

            arr.push(obj)
        }

        res.status(200).json({
            message: "Customers Fetched Successfully",
            data: arr,
            status: true
        })

    } catch (err) {
        if (!err.statusCode) {
            err.statusCode = 500
        }
        next(err)
    }
}
