exports.getCurtainFabric = async (req, res, next) => {
    try {
        const category = req.query.category;
        let where = {};

        // Apply category filter if provided
        if (category == "fabric") {
            where.item_group = { [Op.in]: ["FABRIC BR", "FABRIC FF", "FABRICS", "FABRIC AD", "FABRIC DIV", "Leatherett", "FABRICS BR"] }
        }
        if (category == "wallpaper") {
            where.item_group = { [Op.in]: ["WALLCOVER", "WALLPAPER"] }  
        }
        if (category == "flooring") {
            where.item_group = "FLOORINGS"
        }
        if (category == "blinds") {
            where.item_group = { [Op.in]: ["BLINDS", "RODS"] }
        }
        if (category == "rods" || category == "track") {
            where.item_group = "RODS"
        }
        if (category == "carpet") {
            where.item_group = { [Op.in]: ["WTW CARPET", "CARPET TIL", "CARPET TILE"] }
        }
        if (category == "cartage") {
            where.item_group = "F&C"
        }

        const curtainQuery = req.query.curtain;
        let fabricCondition = {};

        if (curtainQuery) {
            fabricCondition = {
                [Op.or]: [
                    { fabric: { [Op.like]: "%" + curtainQuery + "%" } },
                    { item_id: { [Op.like]: "%" + curtainQuery + "%" } }
                ]
            };
        }

        fabricCondition.is_blocked = false

        const limitedData = await CurtainFabric.findAll({
            limit: 20,
            where: {
                [Op.and]: [fabricCondition, where],
            },
            include: {
                model: Book,
                include: Brand
            }
        });

        const allData = await CurtainFabric.findAll({
            where: { is_blocked: false },
            include: {
                model: Book,
                include: Brand
            },
            limit: 100,
        });

        const obj = {
            curtainFabric: curtainQuery ? limitedData : allData,
            curtainStyle: await CurtainStyle.findAll(),
            lining: await Liniing.findAll(),
            gathering: await Gathering.findAll(),
            pattern: await CurtainPattern.findAll(),
            ring_color: ["golden", "silver", "antique"]
        };

        res.status(200).json({
            message: "Curtain fetched",
            data: obj,
            status: true
        });
    } catch (err) {
        if (!err.statusCode) {
            err.statusCode = 500;
        }
        next(err);
    }
};

