exports.postMaterial = async (req, res, next) => {
    try {
        const { file, body } = await UploadFile(req, "/assets/fabricData")
        const allDataArray = []
        const result = await sequelize.transaction(async (t) => {

            if (req.body.mainFabric1) {
                const curtain = await SelectedCurtain.findOne({ where: { roomId: req.body.roomId } })
                dataFound(curtain, 400, "Room Style Already Submitted")
                const newCurtainData = await SelectedCurtain.create({
                    roomId: req.body.roomId,
                    enquiryId: req.body.enquiryId,
                    mainFabric1: req.body.mainFabric1,
                    mock_fabric_required: req.body.mock_fabric_required,
                    mock_hand_hammering_required: req.body.mock_hand_hammering_required,
                    mockFabric: req.body.mockFabric,
                    mock_fabric_gathering: req.body.mock_fabric_gathering,
                    fabric_gathering: req.body.fabric_gathering,
                    curtain_style: req.body.curtain_style,
                    mainFabric2: req.body.mainFabric2,
                    pattern: req.body.pattern,
                    LiningFabric: req.body.liningFabric,
                    LiningType: req.body.LiningType,
                    beltType: req.body.beltType,
                    beltFabric: req.body.beltFabric,
                    beltBorderFabricId: req.body.beltBorderFabricId,
                    beltPipingFabricId: req.body.beltPipingFabricId,
                    primaryBorderFabric: req.body.primaryBorderFabric,
                    secondaryBorderFabric: req.body.secondaryBorderFabric,
                    borderType: req.body.borderType,
                    pelmetFabric: req.body.pelmetFabric,
                    weight_required: req.body.curtain_weight_required,
                    hand_hammering_required: req.body.curtain_hand_hammering_required,
                    lining_required: req.body.lining_required,
                    lining_width: req.body.lining_width,
                    belt_required: req.body.belt_required,
                    beltLength: req.body.beltLength,
                    border_required: req.body.border_required,
                    pelmet_required: req.body.pelmet_required,
                    pelmetTypeId: req.body.pelmetTypeId,
                    pelmet_style: req.body.pelmet_style,
                    pelmet_width: req.body.pelmet_width,
                    pelmet_drop: req.body.pelmet_drop,
                    pelmet_turning: req.body.pelmet_turning,
                    pelmet_LBracket_required: req.body.pelmet_LBracket_required,
                    pelmet_LBracket_quantity: req.body.pelmet_LBracket_quantity,

                }, { transaction: t })
                allDataArray.push(newCurtainData)
            }
            if (req.body.sheerFabricId) {
                const sheer = await SelectedSheer.findOne({ where: { roomId: req.body.roomId } })
                dataFound(sheer, 400, "Room Style Already Submitted")
                const newSheerData = await SelectedSheer.create({
                    handHammering: req.body.sheerHandHammering,
                    SheerStyleId: req.body.SheerStyleId,
                    leadChain: req.body.leadChain,
                    sheerFabricId: req.body.sheerFabricId,
                    roomId: req.body.roomId,
                    bracket: req.body.bracket,
                    sheerGathering: req.body.sheerGathering,
                    enquiryId: req.body.enquiryId
                }, { transaction: t })

                allDataArray.push(newSheerData)
            };
            if (req.body.track_required) {
                const track = await SelectedTrack.findOne({ where: { roomId: req.body.roomId } })
                if (track) {
                    return res.status(400).json({
                        message: "Track Already exists",
                        status: false
                    })
                }
                else {
                    await SelectedTrack.create({
                        track_required: req.body.track_required,
                        track_selection: req.body.track_selection,
                        primary_track_type: req.body.primary_track_type,
                        roomId: req.body.roomId
                    })
                }
            }
            if (req.body.rod_required || req.body.rod_selection || req.body.primary_rod_type) {
                const rod = await SelectedRod.findOne({ where: { roomId: req.body.roomId } })
                if (rod) {
                    return res.status(400).json({
                        message: "Rods Already exists",
                        status: false
                    })
                }
                else {
                    await SelectedRod.create({
                        rod_required: req.body.rod_required,
                        rod_selection: req.body.rod_selection,
                        primary_rod_type: req.body.primary_rod_type,
                        roomId: req.body.roomId
                    })
                }
            }
        });


        res.status(201).json({
            message: "Data inserted",
            data: allDataArray,
            status: true
        })
    } catch (err) {
        if (!err.statusCode) {
            err.statusCode = 500
        }
        next(err)
    }
}
