exports.submitTokenAmount = async (req, res, next) => {
    try {
        const enquiry = await Enquiry.findOne({ where: { id: req.params.id }, include: [User, Customer] });
        if (enquiry.status == "cancelled") {
            throw new Error("Enquiry Cancelled")
        }
        const rooms = await Room.findAll({ where: { enquiryId: enquiry.id }, include: { model: SelectedMaterial, include: Material } })
        for (let i = 0; i < rooms.length; i++) {
            const room = rooms[i];
            for (let j = 0; j < room.selectedmaterials.length; j++) {
                const firstMaterial = room.selectedmaterials[j];
            }
        }

        if (req.body.expected_delivery_date) {
            await EnquiryStatus.create({
                remark: "Delivery Date Updated",
                status: "completed",
                enquiryId: req.params.id,
                details: {
                    "date": req.body.expected_delivery_date
                }
            })
        }

        enquiry.amount = req.body.amount;
        enquiry.expected_delivery_date = req.body.expected_delivery_date
        enquiry.expected_installation_date = req.body.expected_installation_date

        await enquiry.save()
        await enquiry.reload()

        if (req.body.payment_type == "online" && req.body.amount) {

            const data = await sendPaymentLink(enquiry.id, req.body.amount, "enquiry_advance");
            const paymentLink = data.short_url

            const message_data = await Message.findOne({ where: { enquiryId: enquiry.id, message: 'advance_payment_message' } });
            const customer = await Customer.findOne({ where: { id: enquiry.customerId } })
            if (!message_data) {
                await Message.create({
                    message: "advance_payment_message",
                    enquiryId: enquiry.id
                })
                const message = advance_payment_message(customer.firstName + ' ' + customer.lastName, paymentLink, req.body.amount)
                whatsappMessage(message, customer.primary_phone);
            }
        }
        // else {
        //     await EnquiryStatus.create({
        //         remark: "Advance Received for Enquiry",
        //         status: "completed",
        //         enquiryId: req.params.id
        //     })
        // }


        res.status(200).json({
            message: "Token Amount Submitted",
            data: rooms,
            status: true
        })
    } catch (err) {
        if (!err.statusCode) {
            err.statusCode = 500
        }
        next(err)
    }
};

