exports.editRoom = async (req, res, next) => {
    try {
        const room = await Room.findOne({ where: { id: req.params.id } })

        if (!room) {
            return res.status(404).json({
                message: "No room found",
                status: false
            })
        }

        if (room.numberOfWindow != req.body.window) {
            const roomasset = await RoomAsset.findAll({ where: { roomId: req.params.id } })
            for (var i = 0; i < roomasset.length; i++) {
                await roomasset[i].destroy()
            }
            for (var k = 0; k < req.body.window; k++) {
                const roomAsset = await RoomAsset.create({
                    roomId: room.id
                })
            }
        }

        room.roomName = req.body.roomName;
        room.roomDescription = req.body.roomDescription;
        room.numberOfWindow = req.body.window
        room.floor = req.body.floor

        room.save();
        room.reload();

        const material = await SelectedMaterial.findAll({ where: { roomId: req.params.id } })
        for (var j = 0; j < material.length; j++) {
            material[j].destroy();
        }

        for (var i = 0; i < req.body.materialSelected.length; i++) {
            const newMaterialData = await SelectedMaterial.create({
                materialId: req.body.materialSelected[i],
                roomId: req.params.id,
                enquiryId: room.enquiryId
            })
        }
        res.status(200).json({
            message: "Room edited",
            status: true
        })
    } catch (err) {
        if (!err.statusCode) {
            err.statusCode = 500
        }
        next(err)
    }
};
exports.deleteRoom = async (req, res, next) => {
    try {

        const room = await Room.findOne({ where: { id: req.params.id } })
        dataNotFound(room, 404, "No room found")

        const roomasset = await RoomAsset.findAll({ where: { roomId: room.id } })

        if (roomasset.length > 0) {
            for (var i = 0; i < roomasset.length; i++) {
                const item = roomasset[i]

                await SelectedBlind.destroy({ where: { roomAssetId: item.id } });
                await item.destroy()
            }
        }

        const wall = await Wall.findAll({ where: { roomId: room.id } });
        if (wall.length > 0) {
            for (var i = 0; i < wall.length; i++) {
                await WallpaperArea.destroy({ where: { wallId: wall[i].id } })

                await wall[i].destroy()
            }
        }
        await SelectedTrack.destroy({ where: { roomId: room.id } })
        await SelectedSheer.destroy({ where: { roomId: room.id } })
        await SelectedRod.destroy({ where: { roomId: room.id } })
        await SelectedMaterial.destroy({ where: { roomId: room.id } })
        await SelectedFlooring.destroy({ where: { roomId: room.id } })
        await SelectedCurtain.destroy({ where: { roomId: room.id } })
        await SelectedSofa.destroy({ where: { roomId: room.id } });
        await room.destroy();

        res.status(200).json({
            message: "Room deleted",
            status: true
        })
    } catch (err) {
        if (!err.statusCode) {
            err.statusCode = 500
        }
        next(err)
    }
};

function dhm(ms) {
    const days = Math.floor(ms / (24 * 60 * 60 * 1000));
    const daysms = ms % (24 * 60 * 60 * 1000);
    const hours = Math.floor(daysms / (60 * 60 * 1000));
    const hoursms = ms % (60 * 60 * 1000);
    const minutes = Math.floor(hoursms / (60 * 1000));
    const minutesms = ms % (60 * 1000);
    const sec = Math.floor(minutesms / 1000);
    return days + ":" + hours + ":" + minutes + ":" + sec;
}

