exports.getCustomerByName = async (req, res, next) => {
    try {
        // const user = await User.findByPk(req.userId);
        const where_clouse = {};

        // if(user.type == "sales-person"){
        //     where_clouse.salesId = user.id
        // }

        const fullName = req.query.data || '';
        const data = await Customer.count({
            where: {
                [Op.or]:
                    [{ primary_email: { [Op.like]: "%" + req.query.data + "%" } },
                    { secondary_email: { [Op.like]: "%" + req.query.data + "%" } },
                    { primary_phone: { [Op.like]: "%" + req.query.data + "%" } },
                    { secondary_phone: { [Op.like]: "%" + req.query.data + "%" } },
                    {
                        [Op.or]: [
                            sequelize.where(
                                sequelize.fn('CONCAT', sequelize.col('firstName'), ' ', sequelize.col('lastName')),
                                'LIKE',
                                `%${fullName}%`
                            ),
                            sequelize.where(
                                sequelize.fn('CONCAT', sequelize.col('lastName'), ' ', sequelize.col('firstName')),
                                'LIKE',
                                `%${fullName}%`
                            )
                        ]
                    }],
                ...where_clouse
            }
        })
        let page = req.query.page || 1;      // page number
        let limit = 30;   // number of records per page
        let pages = Math.ceil(data / limit);
        let offset = limit * (page - 1);

        const customer = await Customer.findAll({
            limit, offset,
            where: {
                [Op.or]:
                    [{ primary_email: { [Op.like]: "%" + req.query.data + "%" } },
                    { secondary_email: { [Op.like]: "%" + req.query.data + "%" } },
                    { primary_phone: { [Op.like]: "%" + req.query.data + "%" } },
                    { secondary_phone: { [Op.like]: "%" + req.query.data + "%" } },
                    {
                        [Op.or]: [
                            sequelize.where(
                                sequelize.fn('CONCAT', sequelize.col('firstName'), ' ', sequelize.col('lastName')),
                                'LIKE',
                                `%${fullName}%`
                            ),
                            sequelize.where(
                                sequelize.fn('CONCAT', sequelize.col('lastName'), ' ', sequelize.col('firstName')),
                                'LIKE',
                                `%${fullName}%`
                            )
                        ]
                    }],
                ...where_clouse
            },
            order: [["id", "DESC"]]
        })

        const arr = []
        for (var i = 0; i < customer.length; i++) {

            const billingAddress = await Address.findOne({ where: { customerId: customer[i].id, type: "billing" } });

            const deliveryAddress = await Address.findOne({ where: { customerId: customer[i].id, type: "delivery" } });

            const obj = {
                customer: customer[i],
                billing: billingAddress ? billingAddress : null,
                delivery: deliveryAddress ? deliveryAddress : null
            }

            arr.push(obj)
        }
        res.status(200).json({
            message: "Data Found",
            status: true,
            data: arr,
            pages
        })
    } catch (err) {
        if (!err.statusCode) {
            err.statusCode = 500
        }
        next(err)
    }
}

