                            areaItems.t_profile_quantity += area.t_profile_quantity
                            areaItems.t_profile_cost += (area.t_profile.price * area.t_profile_quantity) - ((area.t_profile.price * area.t_profile_quantity) * (area.t_profile_discount / 100))
