exports.getLadder = async (req, res, next) => {
    try {
        let ledderId = 4
        if (req.query.height > 563.88) {
            ledderId = 1
        }
        if (req.query.height < 563.88) {
            ledderId = 2
        }
        if (req.query.height < 289.56) {
            ledderId = 3
        }
        const ladder = await Ladder.findByPk(ledderId);
        return res.status(200).json({
            message: "data fatched seccessfully",
            status: true,
            data: ladder
        })
    } catch (e) {
        next(e)
    }
}


